/* Theme foundation */
/* ============================================================
   VANO V56 — white + purple system, automatic Black mode
   Official brand purple: #F59A62 / #FFC39B
   ============================================================ */
body.vano-live-v258{
  --vano:#F59A62;
  --vano-2:#FFC39B;
  --vano-deep:#D9703F;
  --vano-soft:#FFF4EC;
  --vano-soft-2:#FFFBF2;
  --vano-bg:#F6F7FB;
  --vano-card:#FFFFFF;
  --vano-card-2:#FAFAFD;
  --vano-ink:#171A2B;
  --vano-muted:#687386;
  --vano-line:#E3E6EE;
  --vano-line-strong:#D6DAE5;
  --vano-shadow:0 12px 34px rgba(32,38,70,.08);
  --vano-shadow-lg:0 28px 80px rgba(32,38,70,.13);
  --vano-radius:18px;
  /* Legacy aliases: old orange branding becomes VANO purple. Traffic/alerts
     that use dedicated hard-coded warning colors remain functional. */
  --orange:#F59A62;
  --orange-2:#FFC39B;
  --orange-3:#FFC39B;
  --bg:#F6F7FB;
  --surface:#FFFFFF;
  --surface-2:#F8F9FC;
  --surface-3:#F0F2F7;
  --text:#171A2B;
  --muted:#687386;
  --muted-2:#8891A1;
  --line:#E3E6EE;
  --shadow:var(--vano-shadow);
}
