body.vano-map-surface .search-results{border:1px solid var(--vg-line)!important;border-radius:18px!important;background:rgba(255,255,255,.99)!important;color:var(--vg-ink)!important;box-shadow:0 22px 60px rgba(39,35,31,.16)!important;padding:6px!important}body.vano-map-surface .search-item{border-radius:13px!important}body.vano-map-surface .search-item:active{background:#F4F4F8!important}body.vano-map-surface .result-icon{background:var(--vg-brand-soft)!important;color:var(--vg-brand)!important}body.vano-map-surface .result-copy b{color:var(--vg-ink)!important}body.vano-map-surface .result-copy small,
