    max-width:var(--v100-wide)!important;
    height:var(--v100-wide-h)!important;
    min-height:var(--v100-wide-h)!important;
    max-height:var(--v100-wide-h)!important;
    margin:0!important;
    padding:0 8px!important;
    border-radius:15px!important;
    flex:0 0 var(--v100-wide-h)!important;
  }

  /* Voice popover follows the right rail instead of covering the ETA bar. */
}

@media(max-width:380px){
  body.vano-map-surface.body-nav .ws-app{
    --v100-edge:max(7px, calc(env(safe-area-inset-left) + 5px));
    --v100-edge-right:max(7px, calc(env(safe-area-inset-right) + 5px));
    --v100-wide:64px;
    --v100-wide-h:42px;
    --v100-round:42px;
  }
}

/* =====================================================================
   VANO V101 — DRIVER FIRST / CLEAN MAP UI
   Front-end only. Keeps all legacy IDs/hooks alive for v100 JS while
   reducing chrome, composite effects and distraction around the map.
   ===================================================================== */
body.vano-map-surface{
  --v101-accent:#D9703F;
  --v101-accent-soft:#FFF2E8;
  --v101-ink:#15171c;
  --v101-copy:#6d7280;
  --v101-line:rgba(22,24,29,.09);
  --v101-surface:rgba(255,255,255,.985);
  --v101-shadow:0 10px 32px rgba(18,22,33,.10),0 2px 8px rgba(18,22,33,.05);
  --v101-shadow-soft:0 6px 18px rgba(18,22,33,.08);
  --v101-radius:24px;
}

body.vano-map-surface,
body.vano-map-surface button,
body.vano-map-surface input,
body.vano-map-surface select,
body.vano-map-surface textarea{
  font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display","SF Pro Text",Inter,system-ui,sans-serif!important;
  -webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;
}

/* Keep the map itself visually dominant. Heavy atmospheric layers caused
   extra GPU composition and made road labels harder to read. */
body.vano-map-surface .map-vignette,
body.vano-map-surface .ambient-halo,
body.vano-map-surface .road-mood-hint{display:none!important}
body.vano-map-surface .map-mood-fade{pointer-events:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important}

/* Healthy GPS is silent. Surface only actionable states elsewhere. */
body.vano-map-surface .status-chip,
body.vano-map-surface .gps-quality{display:none!important}

/* Common materials: almost opaque instead of full-screen blur. */
body.vano-map-surface #planSheet,
body.vano-map-surface .options-btn,
body.vano-map-surface .map-tools .map-btn,
body.vano-map-surface .floating-locate,
body.vano-map-surface .nav-maneuver-top,
body.vano-map-surface .nav-street-chip,
body.vano-map-surface #activeNav,
body.vano-map-surface .nav-stack-btn,
body.vano-map-surface .nav-drawer-toggle,
body.vano-map-surface .nav-drawer-btn,
body.vano-map-surface .traffic-radar,
body.vano-map-surface .nav-alt-hint,
body.vano-map-surface .destination-confirm{
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
}

body.vano-map-surface .header{z-index:55!important;top:max(12px,calc(env(safe-area-inset-top) + 8px))!important;right:max(12px,calc(env(safe-area-inset-right) + 10px))!important;left:auto!important;width:auto!important}
body.vano-map-surface .header-actions{display:flex!important;gap:8px!important}
body.vano-map-surface .options-btn{
  width:46px!important;height:46px!important;padding:0!important;border-radius:16px!important;
  border:1px solid var(--v101-line)!important;background:var(--v101-surface)!important;color:#565c69!important;
  box-shadow:var(--v101-shadow-soft)!important;display:grid!important;place-items:center!important;
  transition:transform .14s ease,background .14s ease!important;
}
body.vano-map-surface .options-btn:active{transform:scale(.94)!important;background:#f6f6f8!important}

/* One calm safety entry on the free map. The detailed alert/report tools stay
   available inside their existing sheet, but no longer crowd the map. */
body.vano-map-surface .map-tools{top:max(68px,calc(env(safe-area-inset-top) + 64px))!important;right:max(12px,calc(env(safe-area-inset-right) + 10px))!important;gap:0!important}
body.vano-map-surface .map-tools #quickAlertBtn,
body.vano-map-surface .map-tools #focusModeBtn{display:none!important}
body.vano-map-surface .map-tools #safetyToolsBtn{
  display:grid!important;width:46px!important;height:46px!important;border-radius:16px!important;
  background:var(--v101-surface)!important;border:1px solid var(--v101-line)!important;
  color:var(--v101-accent)!important;box-shadow:var(--v101-shadow-soft)!important;
}

/* Free-map destination planner: compact navigation search first. */
body.vano-map-surface:not(.body-nav) #planSheet{
  left:max(12px,calc(env(safe-area-inset-left) + 10px))!important;
  right:max(12px,calc(env(safe-area-inset-right) + 10px))!important;
