  padding:8px 10px 10px!important;border:1px solid var(--v101-line)!important;
  border-radius:28px!important;background:var(--v101-surface)!important;
  box-shadow:var(--v101-shadow)!important;color:var(--v101-ink)!important;
  overflow:visible!important;
  transition:height .24s cubic-bezier(.22,.8,.24,1),max-height .24s cubic-bezier(.22,.8,.24,1),transform .2s ease!important;
}
