body.vano-map-surface .planner-location-row.location-row{height:54px!important;min-height:54px!important;grid-template-columns:42px minmax(0,1fr) 42px!important}
body.vano-map-surface .planner-search-icon{color:#777c86!important}
body.vano-map-surface .planner-search-card .location-input{
