}
body.vano-map-surface .planner-adjust-btn:active{transform:scale(.95)!important;background:#e9e9ed!important}
body.vano-map-surface .planner-presets{gap:8px!important;margin-top:9px!important}
body.vano-map-surface .planner-preset{
  min-height:56px!important;padding:8px 10px!important;border:0!important;border-radius:17px!important;background:#f5f5f7!important;box-shadow:none!important;
}
body.vano-map-surface .planner-preset-icon{background:#fff!important;color:var(--v101-accent)!important;box-shadow:0 1px 4px rgba(0,0,0,.05)!important}
body.vano-map-surface .nearby-service{background:#f5f5f7!important;border:0!important;border-radius:17px!important}
body.vano-map-surface .nearby-service-icon{background:#fff!important;color:var(--v101-accent)!important}
body.vano-map-surface .planner-tip{background:#FFF4EC!important;color:#706861!important}
body.vano-map-surface .search-results{
  border:1px solid var(--v101-line)!important;border-radius:20px!important;background:#fff!important;
  box-shadow:0 18px 40px rgba(18,22,33,.14)!important;overflow:hidden!important;
}

/* Recenter follows the compact sheet rather than floating high in the map. */
body.vano-map-surface:not(.body-nav) .floating-locate{
  display:grid!important;place-items:center!important;width:46px!important;height:46px!important;
  right:max(14px,calc(env(safe-area-inset-right) + 12px))!important;
