/* Nearby users notice */
/* VANO V133 — nearby users notice + compact map brand.
   Isolated from the planner/map styles so it cannot reflow the existing UI. */

.vano-nearby-users-notice{
  position:absolute;
  z-index:53;
  contain:layout style paint;
  left:50%;
  bottom:180px;
  width:max-content;
  max-width:min(520px,calc(100vw - 28px));
  min-height:54px;
  backdrop-filter:blur(18px) saturate(130%);
  -webkit-backdrop-filter:blur(18px) saturate(130%);
  box-sizing:border-box;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  padding:9px 16px 9px 10px;
  border:1px solid rgba(217,112,63,.10);
  border-radius:999px;
  background:rgba(255,255,255,.97);
  color:#1a2140;
  box-shadow:0 13px 36px rgba(36,39,70,.12),0 3px 10px rgba(217,112,63,.08),inset 0 1px 0 rgba(255,255,255,.72);
  opacity:0;
  visibility:hidden;
  pointer-events:none;
  transform:translate(-50%,16px) scale(.985);
  transform-origin:center bottom;
  will-change:transform,opacity;
  transition:
    opacity .36s ease,
    transform .48s cubic-bezier(.18,.82,.22,1),
    visibility .36s ease;
}
.vano-nearby-users-notice::after{
  content:"";
  position:absolute;
  inset:auto 12% -13px;
  height:24px;
  border-radius:50%;
  background:rgba(217,112,63,.12);
  filter:blur(13px);
  opacity:.56;
  z-index:-1;
}
.vano-nearby-users-notice.is-visible{
  opacity:1;
  visibility:visible;
  transform:translate(-50%,0) scale(1);
}
.vano-nearby-users-notice.is-leaving{
  opacity:0;
  visibility:visible;
  transform:translate(-50%,20px) scale(.985);
  transition-duration:.34s,.44s,.34s;
}
.vano-nearby-users-icon{
  position:relative;
  flex:0 0 38px;
  width:38px;
  height:38px;
  display:grid;
  place-items:center;
  border-radius:50%;
  color:#D9703F;
  background:linear-gradient(145deg,#FFFBF2,#FFFBF2);
  box-shadow:inset 0 0 0 1px rgba(217,112,63,.07),0 3px 9px rgba(217,112,63,.08);
}
.vano-nearby-users-icon::before{
  content:"";
  position:absolute;
  inset:-4px;
  border-radius:50%;
  border:1px solid rgba(217,112,63,.12);
  opacity:0;
  transform:scale(.82);
}
.vano-nearby-users-notice.is-visible .vano-nearby-users-icon::before{
  animation:vanoNearbyPulse 1.05s .16s ease-out 1 both;
}
.vano-nearby-users-icon svg{
  width:20px;
  height:20px;
  display:block;
  stroke:currentColor;
  stroke-width:2;
  fill:none;
  stroke-linecap:round;
  stroke-linejoin:round;
}
.vano-nearby-users-copy{
  display:block;
  min-width:0;
  max-width:430px;
  font-size:13px;
  line-height:1.24;
  letter-spacing:-.16px;
  font-weight:720;
  color:#222956;
  white-space:normal;
  text-wrap:balance;
}
.vano-nearby-users-copy strong{
  font-weight:880;
  color:#D9703F;
}

body.body-nav .vano-nearby-users-notice,
body.vano-keyboard-open .vano-nearby-users-notice,
html.vano-keyboard-open .vano-nearby-users-notice{
  opacity:0!important;
  visibility:hidden!important;
  transform:translate(-50%,18px) scale(.985)!important;
}

