  }
}

/* iPad / large Android tablet in landscape often reports notebook width. */
@media(min-width:1024px) and (max-width:1366px) and (pointer:coarse){
  body.vano-map-surface.vano-map-surface:not(.body-nav) #planSheet{
    width:clamp(390px,40vw,460px)!important;
    left:max(16px,env(safe-area-inset-left))!important;
    top:max(16px,env(safe-area-inset-top))!important;
    bottom:max(16px,env(safe-area-inset-bottom))!important;
  }
  body.vano-map-surface .destination-confirm,
  body.vano-map-surface #resumeTripCard{
    width:clamp(390px,40vw,460px)!important;
    left:max(16px,env(safe-area-inset-left))!important;
    bottom:max(16px,env(safe-area-inset-bottom))!important;
  }
  body.vano-map-surface :is(#accountDrawer,#prefsDrawer,#safetyDrawer,#quickAlertSheet){
    width:min(450px,44vw)!important;
    right:max(16px,env(safe-area-inset-right))!important;
    bottom:max(16px,env(safe-area-inset-bottom))!important;
  }
  body.vano-map-surface button{min-block-size:44px}
}

/* Touch notebook/tablet with an on-screen keyboard. */

/* Short notebooks: compress secondary blocks, never core route CTA. */
@media(min-width:900px) and (max-height:720px){
  body.vano-map-surface.vano-map-surface:not(.body-nav) #planSheet{
    top:10px!important;bottom:10px!important;
    max-height:calc(var(--vano-vh,100dvh) - 20px)!important;
    padding-top:13px!important;padding-bottom:13px!important;
  }
  body.vano-map-surface .planner-tip{display:none!important}
  body.vano-map-surface .nearby-service{min-height:58px!important}
  body.vano-map-surface #routeState .vano-route-more-section{margin-top:8px!important}
  body.vano-map-surface.body-nav #navManeuverTop{top:10px!important}
  body.vano-map-surface.body-nav #activeNav.nav-panel.nav-minimal{bottom:10px!important}
}

/* Ultrawide: do not let UI scale with empty horizontal space. */
@media(min-width:2200px){
  body.vano-map-surface.vano-map-surface:not(.body-nav) #planSheet{width:520px!important}
  body.vano-map-surface .destination-confirm,
  body.vano-map-surface #resumeTripCard{width:520px!important}
  body.vano-map-surface :is(#accountDrawer,#prefsDrawer,#safetyDrawer,#quickAlertSheet){width:480px!important}
  body.vano-map-surface.body-nav #navManeuverTop,
  body.vano-map-surface.body-nav #activeNav.nav-panel.nav-minimal{width:530px!important}
}

/* Prevent accidental horizontal growth from long localized strings. */
body.vano-map-surface :is(
  .planner-heading-copy,.planner-tip,.route-option-copy,.route-card,.route-ai,
  .nav-maneuver-copy,.quick-alert-copy){
  min-width:0!important;
  overflow-wrap:anywhere;
}

/* 2026-10 route sheet: readable options and expandable content at narrow widths. */
body.vano-map-surface #routeState {width:min(100%, 520px)!important;max-width:calc(100vw - 16px)!important;box-sizing:border-box!important;}
body.vano-map-surface #routeState :is(.route-variants,.vano-route-more,.vano-route-more-content,.route-card,.route-deep-grid){min-width:0!important;max-width:100%!important;box-sizing:border-box!important;}
body.vano-map-surface #routeState .route-variants{display:grid!important;grid-template-columns:repeat(auto-fit,minmax(min(100%,160px),1fr))!important;gap:10px!important;overflow:visible!important;}
body.vano-map-surface #routeState .route-variants > *{min-width:0!important;min-height:58px!important;height:auto!important;white-space:normal!important;overflow-wrap:anywhere!important;}
body.vano-map-surface #routeState .route-variants :is(button,b,small,span){max-width:100%;min-width:0;overflow-wrap:anywhere;white-space:normal!important;}
body.vano-map-surface #routeState #routeMoreDetails[data-open="true"]{height:auto!important;max-height:min(68dvh,640px)!important;overflow-y:auto!important;overscroll-behavior:contain;}
body.vano-map-surface #routeState #routeMoreContent{height:auto!important;max-height:none!important;overflow:visible!important;}
body.vano-map-surface #routeState #routeMoreContent :is(.travel,.route-deep-grid){min-width:0!important;max-width:100%!important;}
body.vano-map-surface #routeState #routeMoreContent button{min-height:44px!important;height:auto!important;white-space:normal!important;overflow-wrap:anywhere!important;}
@media(max-width:420px){body.vano-map-surface #routeState{max-width:calc(100vw - 12px)!important;}body.vano-map-surface #routeState .route-variants{grid-template-columns:1fr!important;}body.vano-map-surface #routeState #routeMoreContent .travel{grid-template-columns:repeat(2,minmax(0,1fr))!important;}body.vano-map-surface #routeState #routeMoreContent .travel button{padding:10px 8px!important;}}
html[data-vano-theme="black"] body:not(.vano-admin-surface) :is(h1,h2,h3,h4,.vr-section-head,.vano-route-more-toggle-copy b,.route-option-copy b,.route-card-top h3){color:#f5f6f8!important;}
html[data-vano-theme="black"] body.vano-map-surface #routeState :is(.vr-section-head span,.vr-copy b,.route-variants b,.route-card b,.vano-route-more-section-head span){color:#f5f6f8!important;}
